Q: Existential types in C#? A: <p>You can use church encoding for existential type, c# can support generic function in interface, so it can easy implemented.</p>
<pre><code>using System;
using System.Collections.Generic;

public interface IMyInterface&lt;T&gt;
{
    T GetSomething();
    void DoSomething(T value);
}

public interface IConsumer
{
    void Invoke&lt;T&gt;(IMyInterface&lt;T&gt; value);
}

public interface ISomeMyInterface
{
    void Accept(IConsumer consumer);
}

public sealed class SomeMyInterface&lt;T&gt; : ISomeMyInterface
{
    private readonly IMyInterface&lt;T&gt; value;

    public SomeMyInterface(IMyInterface&lt;T&gt; value)
    {
        this.value = value;
    }

    public void Accept(IConsumer consumer)
    {
        consumer.Invoke(value);
    }
}

public static class SomeMyInterface
{
    public static ISomeMyInterface Pack&lt;T&gt;(IMyInterface&lt;T&gt; value)
    {
        return new SomeMyInterface&lt;T&gt;(value);
    }
}

public sealed class MyIntClass : IMyInterface&lt;int&gt;
{
    public int GetSomething()
    {
        return 42;
    }

    public void DoSomething(int value)
    {
        Console.WriteLine(value);
    }
}

public sealed class MyStringClass : IMyInterface&lt;string&gt;
{
    public string GetSomething()
    {
        return &quot;Something&quot;;
    }

    public void DoSomething(string value)
    {
        Console.WriteLine(value);
    }
}

public sealed class DoSomethingTwice : IConsumer
{
    public void Invoke&lt;T&gt;(IMyInterface&lt;T&gt; value)
    {
        T something = value.GetSomething();

        value.DoSomething(something);
        value.DoSomething(something);
    }
}

public static class Program
{
    public static void Main()
    {
        var things = new List&lt;ISomeMyInterface&gt;
        {
            SomeMyInterface.Pack(new MyIntClass()),
            SomeMyInterface.Pack(new MyStringClass())
        };

        var operation = new DoSomethingTwice();

        foreach (ISomeMyInterface thing in things)
        {
            thing.Accept(operation);
        }
    }
}
</code></pre>
<p>(BTW, I think want you really want is `</p>
<pre class="lang-cs prettyprint-override"><code>MyIntClass : IMyInterface&lt;MyIntClass &gt;
</code></pre>

Q: Laravel Eloquent Eager Loading Multiple Has Many Relationship A: <p>You could create a function within the Students model:</p>

<pre><code>public function questions(){
   $questions = [];
   foreach($this-&gt;homework as $homework){
        foreach($homework-&gt;questions as $question){
           array_push($questions, $question);
        }
   }
   return $questions;
}
</code></pre>

<p>This way every time you have an student object you can get an array of all the questions like this:</p>

<pre><code>$student-&gt;questions
</code></pre>

<p>Hope this could help you.</p>
